    public static void main(String[] args){anyStage();declineAndFail();exclusive();authority();entrySources();stadiumHandOnly();nestedEntryKnockout();direct();locks();concession();ai();schema();System.out.println("NonPokemonBatch130Test passed: Dream Ball both seats and Basic/evolution deck placement, private search/fail-to-find/shuffle, full Bench/empty deck/face-up/Checkup/final exclusions, source-specific entry triggers, Gapejaw Bog hand-only exclusion, synthetic DECK-entry nested KO before remaining Dream Ball and promotion, direct attack resumption, hand lock bypass, source-card visibility/conservation and four AI levels");}
    static void anyStage(){for(UUID p:List.of(A,B))for(boolean evolved:List.of(false,true)){
        var m=game();if(p.equals(B))m.endTurn(A);String id=p.equals(A)?evolved?"evolved":"attacker":evolved?"defender_evolved":"defender";var target=toDeck(m,p,id);var source=prize(m,p,0);int deck=m.privateView(p).deck().size(),held=m.privateView(p).hand().size();m.attack(p,"hit");m.takePrizeAt(p,0);choose(m,p,0);var q=m.effectCardPrompt(p);check(q.candidates().contains(target)&&q.minimum()==0&&q.maximum()==1,"Evolution omitted or hidden search count wrong");int rng=m.randomTranscript().size();search(m,p,target);check(m.benchPokemonView(p).stream().anyMatch(h->h.pokemonId().equals(BenchToActiveEnergyAbilityTest.board(m).pokemonView(p,target.instanceId()).pokemonId()))&&m.privateView(p).deck().size()==deck-1&&m.privateView(p).discard().contains(source)&&m.privateView(p).hand().size()==held,"Dream Ball destination/count wrong seat="+p+" evolved="+evolved+" bench="+m.benchPokemonView(p)+" target="+target+" deck="+m.privateView(p).deck().size()+" expected="+(deck-1)+" hand="+m.privateView(p).hand().size()+" expected="+held+" discarded="+m.privateView(p).discard().contains(source)+" phase="+m.phase());check(m.randomTranscript().size()==rng+Math.max(0,deck-2),"Dream Ball did not shuffle exactly once");NonPokemonBatch103Test.settle(m);
    }}
    static void declineAndFail(){for(boolean decline:List.of(false,true)){var m=game();var source=prize(m,A,0);var deck=List.copyOf(m.privateView(A).deck());m.attack(A,"hit");m.takePrizeAt(A,0);int rng=m.randomTranscript().size();choose(m,A,decline?1:0);if(!decline)search(m,A,null);check(m.privateView(A).hand().contains(source)==decline&&m.privateView(A).discard().contains(source)!=decline&&m.privateView(A).deck().size()==deck.size(),"Decline/fail-to-find destination");check(m.randomTranscript().size()==rng+(decline?0:Math.max(0,deck.size()-1)),"Decline shuffled or fail-to-find skipped shuffle");NonPokemonBatch103Test.settle(m);}
        var m=game();var deck=PairedTrainerPlayTest.zone(m,A,"deck");var pokemon=deck.stream().filter(c->m.cardDefinition(c.definitionId()).category()==CardCategory.POKEMON).toList();deck.removeAll(pokemon);PairedTrainerPlayTest.zone(m,A,"hand").addAll(pokemon);prize(m,A,0);m.attack(A,"hit");m.takePrizeAt(A,0);choose(m,A,0);check(m.effectCardPrompt(A).candidates().isEmpty()&&m.canConfirmEffectCards(A),"No Pokemon deck must still permit failed private search");search(m,A,null);NonPokemonBatch103Test.settle(m);
    }
    static void exclusive(){var m=game();var card=DynamicPassiveModifierTest.hand(m,A,"trainer");check(!m.canPlayTrainer(A,card.instanceId(),null),"Dream Ball playable from hand");reject(()->m.playTrainer(A,card.instanceId(),null));
        for(String mode:List.of("faceup","checkup","last","full","empty")){var n=game();var source=prize(n,A,0);if(mode.equals("faceup"))NonPokemonBatch116Test.faces(n,A).add(source.instanceId());if(mode.equals("last"))GeneratedRuleBatch47Test.remainingPrizes(n,1);if(mode.equals("empty"))n.drawCardsByEffect(A,A,n.privateView(A).deck().size());if(mode.equals("full"))while(n.benchPokemonView(A).size()<5){var next=n.privateView(A).hand().stream().filter(x->n.cardDefinition(x.definitionId()).basicPokemon()).findFirst().orElseThrow();n.playBasicPokemonToBench(A,next.instanceId());}
            if(mode.equals("checkup")){NonPokemonBatch75Test.hurt(n,B,n.activePokemonView(B).pokemonId(),990);n.applySpecialConditionByEffect(A,B,SpecialCondition.POISONED);n.endTurn(A);}else n.attack(A,"hit");n.takePrizeAt(A,0);check(!n.hasPendingEffectChoice()&&n.privateView(A).hand().contains(source),"Dream Ball opened illegal "+mode+" window");if(!mode.equals("last"))NonPokemonBatch103Test.settle(n);
        }
    }
    static void authority(){var m=aiGame(IDS.getFirst());choose(m,A,0);var q=m.effectCardPrompt(A);var candidate=q.candidates().getFirst();var before=m.privateView(A);var rng=m.randomTranscript();reject(()->m.effectCardPrompt(B));reject(()->m.submitEffectCards(B,q.resolutionId(),0,List.of()));reject(()->m.submitEffectCards(A,UUID.randomUUID(),0,List.of()));reject(()->m.submitEffectCards(A,q.resolutionId(),1,List.of()));reject(()->m.submitEffectCards(A,q.resolutionId(),0,List.of(candidate.instanceId(),candidate.instanceId())));reject(()->m.submitEffectCards(A,q.resolutionId(),0,List.of(m.privateView(A).hand().getFirst().instanceId())));check(before.equals(m.privateView(A))&&rng.equals(m.randomTranscript()),"Invalid Dream search changed zones/RNG");
        var session=MatchSession.multiplayer(m,A,B);String opponent=new Gson().toJson(session.view(B,B));for(var card:before.deck())check(!opponent.contains(card.instanceId().toString()),"Dream search leaked deck identities");check(m.clientView(B).resolvingTrainerCards().size()==1,"Declared Dream Ball not publicly visible");m.toggleEffectCard(A,q.resolutionId(),0,candidate.instanceId());check(m.canConfirmEffectCards(A)&&m.effectCardPrompt(A).selected().equals(List.of(candidate.instanceId())),"Draft Dream selection failed");search(m,A,candidate);reject(()->m.submitEffectCards(A,q.resolutionId(),0,List.of()));NonPokemonBatch103Test.settle(m);
    }
    static AbilityDefinition watcher(String source){return BundledCombatData.ability(JsonParser.parseString("{\"id\":\"deck-entry\",\"nameZh\":\"入场来源测试\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_ENTER_PLAY\",\"watch\":\"OWN_FIELD\",\"source\":\""+source+"\",\"optional\":false,\"usage\":\"NONE\"},\"effects\":[{\"type\":\"draw\",\"amount\":1}]}").getAsJsonObject(),EffectRegistry.standard());}
    static void entrySources(){for(String source:List.of("HAND","DECK","ANY")){var c=config();c.source=watcher(source);var m=GeneratedRuleBatch28Test.fixture(c);m.playBasicPokemonToBench(A,DynamicPassiveModifierTest.hand(m,A,"source").instanceId());var target=toDeck(m,A,"evolved");prize(m,A,0);int held=m.privateView(A).hand().size();m.attack(A,"hit");m.takePrizeAt(A,0);choose(m,A,0);search(m,A,target);check(m.privateView(A).hand().size()==held+(source.equals("HAND")?0:1),"Dream entry source wrong "+source);NonPokemonBatch103Test.settle(m);}}
    @SuppressWarnings("unchecked") static void addDreamAlias(ServerMatch m){try{
        var f=ServerMatch.class.getDeclaredField("combat");f.setAccessible(true);var catalog=f.get(m);var t=CombatCatalog.class.getDeclaredField("trainers");t.setAccessible(true);var trainers=new HashMap<>((Map<String,TrainerProfile>)t.get(catalog));trainers.put("dream",profile());t.set(catalog,Map.copyOf(trainers));
        var d=ServerMatch.class.getDeclaredField("definitions");d.setAccessible(true);var defs=(CardDatabase)d.get(m);var list=new ArrayList<>(defs.all());list.add(new CardDefinition("dream","梦境球",CardCategory.TRAINER,TrainerCategory.ITEM,"H",Set.of("international"),false,false,60,Map.of(),EffectSupport.SUPPORTED,null));d.set(m,new CardDatabase(list));
    }catch(Exception e){throw new AssertionError(e);}}
    static CardInstance aliasPrize(ServerMatch m,int slot){var source=prize(m,A,slot);var card=new CardInstance(source.instanceId(),A,"dream");PairedTrainerPlayTest.zone(m,A,"prizes").set(slot,card);return card;}
    static void stadiumHandOnly(){var c=config();c.trainer=NonPokemonBatch2Test.DATA.trainer("swsh10_en_142").orElseThrow();var m=GeneratedRuleBatch28Test.fixture(c);m.playTrainer(A,DynamicPassiveModifierTest.hand(m,A,"trainer").instanceId(),null);addDreamAlias(m);aliasPrize(m,0);var target=toDeck(m,A,"attacker");m.attack(A,"hit");m.takePrizeAt(A,0);choose(m,A,0);search(m,A,target);check(BenchToActiveEnergyAbilityTest.board(m).pokemonView(A,target.instanceId()).damage()==0,"Gapejaw Bog affected DECK entry");NonPokemonBatch103Test.settle(m);}
    // Synthetic source-specific entry trigger tests engine nesting; no claim this is a printed ability.
    static void nestedEntryKnockout(){var c=config();c.defenderPrizes=2;
        var json=JsonParser.parseString("{\"id\":\"entry-ko\",\"nameZh\":\"入场昏厥测试\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_ENTER_PLAY\",\"watch\":\"SELF\",\"source\":\"DECK\",\"optional\":false,\"usage\":\"NONE\"},\"effects\":[{\"type\":\"damage_counter\",\"target\":\"SELF\",\"amount\":2}]}").getAsJsonObject();
        c.restoredProfiles=Map.of("new",new PokemonProfile(20,0,null,null,0,null,0,1,List.of(c.attack),List.of(BundledCombatData.ability(json,EffectRegistry.standard())),EnergyType.FIGHTING));var m=GeneratedRuleBatch28Test.fixture(c);var first=prize(m,A,0);var second=prize(m,A,1);var target=toDeck(m,A,"new");m.attack(A,"hit");m.takePrizeAt(A,0);m.takePrizeAt(A,0);choose(m,A,0);choose(m,A,0);search(m,A,target);
        check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.pendingChoicePlayer().equals(B)&&m.privateView(A).discard().containsAll(List.of(first,target)),"DECK-entry trigger did not KO the Dream Ball entrant before resuming parent Prizes");m.takePrizeAt(B,0);check(m.hasPendingEffectChoice()&&m.pendingChoicePlayer().equals(A)&&!m.privateView(A).hand().contains(second),"Nested entry KO lost remaining Dream Ball");choose(m,A,1);check(m.privateView(A).hand().contains(second)&&m.phase()==MatchPhase.CHOOSE_REPLACEMENT&&m.pendingChoicePlayer().equals(B),"Parent promotion occurred before remaining Dream Ball");NonPokemonBatch103Test.settle(m);
    }
    static void direct(){var c=config();c.attack=NonPokemonBatch128Test.directAttack();var m=GeneratedRuleBatch28Test.fixture(c);var target=toDeck(m,A,"evolved");var deck=PairedTrainerPlayTest.zone(m,A,"deck");deck.remove(target);deck.add(0,target);var source=prize(m,A,0);NonPokemonBatch128Test.prize(m,A,1,"energy");int held=m.privateView(A).hand().size(),turn=m.turnNumber();m.attack(A,c.attack.id());GeneratedRuleBatch47Test.take(m,A,0);GeneratedRuleBatch47Test.take(m,A,0);choose(m,A,0);search(m,A,target);check(m.currentPlayer().equals(B)&&m.turnNumber()==turn+1&&m.privateView(A).hand().size()==held+6&&m.privateView(A).discard().contains(source)&&m.benchPokemonView(A).stream().anyMatch(p->p.pokemonId().equals(BenchToActiveEnergyAbilityTest.board(m).pokemonView(A,target.instanceId()).pokemonId())),"Direct Prize Dream Ball failed to resume attack once");}
    static void locks(){var c=config();c.defenderAttack=DeckDiscardTriggeredAbilityTest.attack(0,TrainerPlayLockTest.lock("ITEM"));var m=GeneratedRuleBatch28Test.fixture(c);m.endTurn(A);m.attack(B,c.defenderAttack.id());var source=prize(m,A,0);var target=toDeck(m,A,"evolved");int history=GeneratedRuleBatch53Test.history(m,"handPlays").size();m.attack(A,"hit");m.takePrizeAt(A,0);choose(m,A,0);search(m,A,target);check(m.privateView(A).discard().contains(source)&&GeneratedRuleBatch53Test.history(m,"handPlays").size()==history,"Prize Dream Ball obeyed hand lock or invented hand play");NonPokemonBatch103Test.settle(m);}
    static void concession(){var m=aiGame(IDS.getFirst());choose(m,A,0);var source=m.clientView(A).resolvingTrainerCards().getFirst();var deck=m.privateView(A).deck();m.concede(B);check(m.privateView(A).discard().contains(source)&&m.privateView(A).deck().equals(deck)&&!m.hasPendingEffectChoice()&&!m.hasPendingCardSelection(),"Concession failed declared Dream disposal or executed search");}
    static void ai(){for(var level:AiDifficulty.values()){var m=aiGame(IDS.getFirst());var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Dream Ball AI stalled "+level);}}
    static void schema(){reject(()->new TrainerEffect(TrainerEffect.Opcode.PRIZE_SEARCH_POKEMON,2,0));reject(()->new TrainerEffect(TrainerEffect.Opcode.PRIZE_SEARCH_POKEMON,1,0,0,1));reject(()->new TrainerProfile(TrainerCategory.SUPPORTER,new TrainerEffect(TrainerEffect.Opcode.PRIZE_SEARCH_POKEMON,1,0)));check(AiEffects.trainer(profile()).has(AiEffects.Role.SEARCH),"AI lacks Dream search role");}
